template <typename IntegerType>
class IntegerToStringConverter {
  public: void* operator new(size_t, void* p) { return p; } void* operator new[](size_t, void* p) { return p; } void* operator new(size_t size) { return ::WTF::Partitions::FastMalloc(size, nullptr); } void operator delete(void* p) { ::WTF::Partitions::FastFree(p); } void* operator new[](size_t size) { return ::WTF::Partitions::FastMalloc(size, nullptr); } void operator delete[](void* p) { ::WTF::Partitions::FastFree(p); } void* operator new(size_t, WTF::NotNullTag, void* location) { true ? (void)0 : ::logging::VoidifyStream(!(location)) & (*::logging::g_swallow_stream); return location; } private: friend class ::WTF::internal::__thisIsHereToForceASemicolonAfterThisMacro;

 public:
  static_assert(std::is_integral<IntegerType>::value,
                "IntegerType must be a type of integer.");

  explicit IntegerToStringConverter(IntegerType input) {


    bool is_negative = base::IsValueNegative(input);
    UnsignedIntegerType value = is_negative ? 0u - static_cast<UnsignedIntegerType>(input) : input;

    size_t pos = buffer_.size();
    do {
      --pos;
      buffer_[pos] = static_cast<LChar>((value % 10) + '0');
      value /= 10;
    } while (value);

    if (is_negative) {
      --pos;
      buffer_[pos] = static_cast<LChar>('-');
    }

    length_ = static_cast<unsigned>(buffer_.size() - pos);
  }

  base::span<const LChar> Span() const {
    return base::span(buffer_).last(length_);
  }

 private:
  using UnsignedIntegerType = typename std::make_unsigned<IntegerType>::type;
  static const size_t kBufferSize = 3 * sizeof(UnsignedIntegerType) +
                                    std::numeric_limits<IntegerType>::is_signed;

  std::array<LChar, kBufferSize> buffer_;
  unsigned length_;
};

