  inline __attribute__((always_inline)) int LineOffset() const;
  inline __attribute__((always_inline)) int ColumnOffset() const;
  inline __attribute__((always_inline)) int ScriptId() const;
  inline __attribute__((always_inline)) Local<Value> SourceMapUrl() const;
  inline __attribute__((always_inline)) Local<Data> GetHostDefinedOptions() const;
