constexpr int ParseDigits(char& c, const char*& pos, const char* const end) {
  int digits = c - '0';



  int num_digits = std::numeric_limits<int>::digits10;
  for (;;) {
    if ((__builtin_expect(false || (pos == end), false))) break;
    c = *pos++;
    if ('0' > c || c > '9') break;
    --num_digits;
    if ((__builtin_expect(false || (!num_digits), false))) break;
    digits = 10 * digits + c - '0';
  }
  return digits;
}

