  [[nodiscard]] bool IntersectsInclusively(const PhysicalRect&) const;



  bool EdgesOnPixelBoundaries() const {
    return !offset.left.HasFraction() && !offset.top.HasFraction() &&
           !size.width.HasFraction() && !size.height.HasFraction();
  }

