inline void Close(ScopedHandleBase<HandleType> ) {
}


inline MojoResult CloseRaw(Handle handle) {
  return MojoClose(handle.value());
}


inline bool operator<(const Handle a, const Handle b) {
  return a.value() < b.value();
}


inline bool operator==(const Handle a, const Handle b) {
  return a.value() == b.value();
}

