inline bool operator==(const LayoutObject& a, const LayoutObject& b) { return &a == &b; } inline bool operator==(const LayoutObject& a, const LayoutObject* b) { return &a == b; } inline bool operator==(const LayoutObject* a, const LayoutObject& b) { return a == &b; } inline bool operator!=(const LayoutObject& a, const LayoutObject& b) { return !(a == b); } inline bool operator!=(const LayoutObject& a, const LayoutObject* b) { return !(a == b); } inline bool operator!=(const LayoutObject* a, const LayoutObject& b) { return !(a == b); }

inline bool LayoutObject::DocumentBeingDestroyed() const {
  return GetDocument().Lifecycle().GetState() >= DocumentLifecycle::kStopping;
}

inline bool LayoutObject::IsCheckContent() const {
  if (StyleRef().StyleType() != kPseudoIdCheck) {
    return false;
  }

  if (IsText() && !IsBR()) {
    return false;
  }
  return true;
}

inline bool LayoutObject::IsBeforeContent() const {
  if (StyleRef().StyleType() != kPseudoIdBefore)
    return false;

  if (IsText() && !IsBR())
    return false;
  return true;
}

inline bool LayoutObject::IsAfterContent() const {
  if (StyleRef().StyleType() != kPseudoIdAfter)
    return false;

  if (IsText() && !IsBR())
    return false;
  return true;
}

inline bool LayoutObject::IsSelectArrowContent() const {
  if (StyleRef().StyleType() != kPseudoIdSelectArrow) {
    return false;
  }

  if (IsText() && !IsBR()) {
    return false;
  }
  return true;
}

inline bool LayoutObject::IsMarkerContent() const {
  if (StyleRef().StyleType() != kPseudoIdMarker)
    return false;

  if (IsText() && !IsBR())
    return false;
  return true;
}

inline bool LayoutObject::IsBeforeOrAfterContent() const {
  return IsBeforeContent() || IsAfterContent();
}




